/**
 * Draw a 96 CSS-pixel stainless-steel tweezer around its gripping point.
 * angle=0 puts the tail above the tip, along negative Y; angles are radians.
 * open is a normalized 0..1 jaw opening. No animation state is retained.
 */
export function drawTweezers(ctx, tipX, tipY, { angle = -0.48, scale = 1, open = 0, opacity = 1 } = {}) {
  if (!ctx || !Number.isFinite(tipX) || !Number.isFinite(tipY)) return;
  if (!Number.isFinite(angle) || !Number.isFinite(scale) || scale <= 0 || !Number.isFinite(opacity)) return;
  const alpha = Math.max(0, Math.min(1, opacity));
  const spread = Math.max(0, Math.min(1, Number.isFinite(open) ? open : 0)) * 3.5;
  if (!alpha) return;

  ctx.save();
  try {
    ctx.translate(tipX, tipY);
    ctx.rotate(angle);
    ctx.scale(scale, scale);
    ctx.globalAlpha *= alpha;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.shadowColor = 'rgba(22, 32, 33, 0.23)';
    ctx.shadowBlur = 1.7;
    ctx.shadowOffsetX = 0.8;
    ctx.shadowOffsetY = 0.6;

    // The inward-facing jaws meet around (0, 0), with a half-pixel resting gap.
    for (const side of [-1, 1]) {
      const x = value => side * value;
      const steel = ctx.createLinearGradient(x(0), 0, x(7.4), 0);
      steel.addColorStop(0, '#48565a');
      steel.addColorStop(0.17, '#879699');
      steel.addColorStop(0.34, '#eaf0ee');
      steel.addColorStop(0.48, '#fbfcf6');
      steel.addColorStop(0.61, '#b6c0bd');
      steel.addColorStop(0.82, '#879492');
      steel.addColorStop(1, '#4d5d60');

      ctx.beginPath();
      ctx.moveTo(x(0.26 + spread), 0);
      ctx.lineTo(x(1.26 + spread), -0.7);
      ctx.bezierCurveTo(x(2.25 + spread), -9, x(5.25 + spread * 0.45), -39, x(6.1), -82);
      ctx.lineTo(x(2.75), -82);
      ctx.bezierCurveTo(x(2.1 + spread * 0.32), -47, x(1.6 + spread), -14, x(0.26 + spread), 0);
      ctx.closePath();
      ctx.fillStyle = steel;
      ctx.fill();
      ctx.strokeStyle = 'rgba(45, 60, 61, 0.62)';
      ctx.lineWidth = 0.42;
      ctx.stroke();
    }

    // A folded steel U joins the two arms, rather than an oversized end cap.
    const fold = ctx.createLinearGradient(-6.1, -96, 6.1, -81);
    fold.addColorStop(0, '#657577');
    fold.addColorStop(0.25, '#e0e6df');
    fold.addColorStop(0.52, '#f7f8ef');
    fold.addColorStop(0.75, '#a1afad');
    fold.addColorStop(1, '#56686b');
    ctx.beginPath();
    ctx.moveTo(-6.1, -82);
    ctx.bezierCurveTo(-6.1, -100, 6.1, -100, 6.1, -82);
    ctx.lineTo(2.75, -82);
    ctx.bezierCurveTo(2.75, -91.5, -2.75, -91.5, -2.75, -82);
    ctx.closePath();
    ctx.fillStyle = fold;
    ctx.fill();
    ctx.strokeStyle = 'rgba(53, 69, 69, 0.55)';
    ctx.lineWidth = 0.4;
    ctx.stroke();

    ctx.shadowColor = 'transparent';
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;

    for (const side of [-1, 1]) {
      const x = value => side * value;
      // Dark inner seam and a fine, interrupted reflection on the outer bevel.
      ctx.beginPath();
      ctx.moveTo(x(2.75), -82);
      ctx.bezierCurveTo(x(2.1 + spread * 0.32), -47, x(1.6 + spread), -14, x(0.26 + spread), -0.25);
      ctx.strokeStyle = 'rgba(32, 47, 51, 0.66)';
      ctx.lineWidth = 0.47;
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(x(5.47), -77);
      ctx.bezierCurveTo(x(5.1 + spread * 0.28), -52, x(3.1 + spread * 0.8), -25, x(1.35 + spread), -7);
      ctx.strokeStyle = 'rgba(255, 255, 244, 0.72)';
      ctx.lineWidth = 0.48;
      ctx.stroke();

      // Two tiny machining marks keep the finish restrained at normal scale.
      for (const y of [-58, -61]) {
        ctx.beginPath();
        ctx.moveTo(x(3.8 + spread * 0.2), y);
        ctx.lineTo(x(5.15 + spread * 0.2), y - 0.45);
        ctx.strokeStyle = 'rgba(75, 91, 92, 0.3)';
        ctx.lineWidth = 0.34;
        ctx.stroke();
      }

      ctx.beginPath();
      ctx.moveTo(x(0.28 + spread), -0.18);
      ctx.lineTo(x(1.2 + spread), -0.67);
      ctx.strokeStyle = '#dce4df';
      ctx.lineWidth = 0.42;
      ctx.stroke();
    }
  } finally {
    ctx.restore();
  }
}

