/**
 * A printed, blue-grey metal precision tweezer, about 220 CSS px long.
 * (tipX, tipY) is the midpoint of its two actual jaws. angle=0 points the tail
 * toward negative Y; open=0..1 spreads the jaws while their folded tail stays fixed.
 */
export function drawTweezers(ctx, tipX, tipY, { angle = -0.48, scale = 1, open = 0, opacity = 1 } = {}) {
  if (!ctx || !Number.isFinite(tipX) || !Number.isFinite(tipY)) return;
  if (!Number.isFinite(angle) || !Number.isFinite(scale) || scale <= 0 || !Number.isFinite(opacity)) return;
  const alpha = Math.max(0, Math.min(1, opacity));
  const opening = Math.max(0, Math.min(1, Number.isFinite(open) ? open : 0));
  if (!alpha) return;

  const shiftFor = (y, jaw, rear = false) => {
    const t = Math.max(0, Math.min(1, (y + 220) / 220));
    return jaw * Math.pow(t, 1.35) - (rear ? 0.9 * Math.sin(t * Math.PI) : 0);
  };
  const handlePath = (c, shift) => {
    const p = (x, y) => [x + shift(y), y];
    c.beginPath();
    c.moveTo(...p(-10.2, -208));
    c.bezierCurveTo(...p(-10.2, -219), ...p(10.2, -219), ...p(10.2, -208));
    c.bezierCurveTo(...p(11.5, -169), ...p(10.6, -95), ...p(7.5, -50));
    c.lineTo(...p(-7.4, -50));
    c.bezierCurveTo(...p(-9.3, -89), ...p(-11.5, -169), ...p(-10.2, -208));
    c.closePath();
  };
  const bladePath = (c, shift) => {
    const p = (x, y) => [x + shift(y), y];
    c.beginPath();
    c.moveTo(...p(0, 0));
    c.bezierCurveTo(...p(-1.2, -6), ...p(-5.9, -17.7), ...p(-8, -23));
    c.bezierCurveTo(...p(-9.9, -28.1), ...p(-8.9, -39.2), ...p(-7.25, -51.5));
    c.lineTo(...p(6.45, -51.5));
    c.bezierCurveTo(...p(4.1, -38.5), ...p(-1.75, -29.5), ...p(-3.65, -24.5));
    c.bezierCurveTo(...p(-3.5, -21.5), ...p(-0.75, -10.7), ...p(0.42, -0.9));
    c.lineTo(...p(0, 0));
    c.closePath();
  };
  const leaf = (c, x, y, length, turn) => {
    c.save(); c.translate(x, y); c.rotate(turn);
    c.beginPath(); c.moveTo(0, 0);
    c.bezierCurveTo(-length * 0.28, -length * 0.45, -length * 0.14, -length * 0.86, 0, -length);
    c.bezierCurveTo(length * 0.32, -length * 0.6, length * 0.3, -length * 0.22, 0, 0);
    c.fillStyle = '#788960'; c.fill();
    c.beginPath(); c.moveTo(0, -0.8); c.lineTo(0, -length * 0.83);
    c.strokeStyle = '#c5d0a3'; c.lineWidth = 0.32; c.stroke(); c.restore();
  };
  const lily = (c, x, y, radius, turn, pink) => {
    c.save(); c.translate(x, y); c.rotate(turn);
    for (let i = 0; i < 6; i += 1) {
      c.save(); c.rotate(i * Math.PI / 3);
      const petal = c.createLinearGradient(0, 1, 0, -radius);
      petal.addColorStop(0, pink ? '#cc88a2' : '#e8afc4');
      petal.addColorStop(0.48, pink ? '#f2c7d5' : '#fff0f4');
      petal.addColorStop(1, '#fffdf5');
      c.beginPath(); c.moveTo(0, 0.8);
      c.bezierCurveTo(-radius * 0.43, -radius * 0.23, -radius * 0.36, -radius * 0.78, 0, -radius);
      c.bezierCurveTo(radius * 0.26, -radius * 0.61, radius * 0.47, -radius * 0.22, 0, 0.8);
      c.fillStyle = petal; c.fill(); c.strokeStyle = '#d9a4b8'; c.lineWidth = 0.28; c.stroke();
      c.beginPath(); c.moveTo(0, -1); c.quadraticCurveTo(-radius * 0.1, -radius * 0.36, 0, -radius * 0.72);
      c.strokeStyle = 'rgba(183,105,137,.45)'; c.lineWidth = 0.26; c.stroke(); c.restore();
    }
    for (let i = 0; i < 5; i += 1) {
      const a = -2.5 + i * 0.62, r = radius * 0.35;
      const sx = Math.cos(a) * r, sy = Math.sin(a) * r;
      c.beginPath(); c.moveTo(0, 0); c.lineTo(sx, sy);
      c.strokeStyle = '#c489a0'; c.lineWidth = 0.3; c.stroke();
      c.beginPath(); c.ellipse(sx, sy, 0.32, 0.7, a, 0, Math.PI * 2);
      c.fillStyle = '#8f405d'; c.fill();
    }
    c.beginPath(); c.arc(0, 0, 0.7, 0, Math.PI * 2); c.fillStyle = '#deb17b'; c.fill(); c.restore();
  };
  const floralPrint = (c, shift) => {
    for (let row = 0; row < 9; row += 1) {
      const y = -65 - row * 16.5;
      for (const x of row % 2 ? [-5.5, 5.5] : [0]) {
        c.beginPath(); c.arc(x + shift(y), y, 1.85, 0, Math.PI * 2);
        c.fillStyle = '#edc6d4'; c.fill();
        c.strokeStyle = 'rgba(255,238,245,.78)'; c.lineWidth = 0.35; c.stroke();
      }
    }
    for (const [y, direction] of [[-135, 1], [-184, -1]]) {
      const cx = shift(y);
      c.beginPath(); c.moveTo(cx - 2 * direction, y + 12);
      c.bezierCurveTo(cx + 4 * direction, y + 3, cx - 4 * direction, y - 4, cx + direction, y - 12);
      c.strokeStyle = '#6d815c'; c.lineWidth = 0.55; c.stroke();
      leaf(c, cx - direction, y + 5, 6.7, -1.05 * direction);
      leaf(c, cx + direction, y - 4, 6.2, 0.94 * direction);
      leaf(c, cx - 2 * direction, y - 10, 4.8, -0.78 * direction);
      lily(c, cx + 1.2 * direction, y - 5, 6.3, -0.18, false);
      lily(c, cx - 2.3 * direction, y + 5.5, 5.7, 0.34, true);
    }
  };

  ctx.save();
  try {
    ctx.translate(tipX, tipY); ctx.rotate(angle); ctx.scale(scale, scale);
    ctx.globalAlpha *= alpha; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    ctx.shadowColor = 'rgba(27,43,48,.27)'; ctx.shadowBlur = 2.4;
    ctx.shadowOffsetX = 1.1; ctx.shadowOffsetY = 1;

    // Rear plate first: a sub-millimetre offset shows the real laminated mechanism.
    for (const rear of [true, false]) {
      const jaw = (rear ? -1 : 1) * (0.23 + opening * 4.1);
      const shift = y => shiftFor(y, jaw, rear);
      const steel = ctx.createLinearGradient(-13, -25, 9, -25);
      for (const [at, colour] of [
        [0, '#27363e'], [0.15, '#657c85'], [0.27, '#e6f4f7'], [0.34, '#fffef5'],
        [0.41, '#526b75'], [0.52, '#253c47'], [0.64, '#b0cbd1'], [0.76, '#f8ffff'],
        [0.85, '#859fa8'], [1, '#3c5460'],
      ]) steel.addColorStop(at, colour);
      bladePath(ctx, shift); ctx.fillStyle = steel; ctx.fill();
      ctx.strokeStyle = rear ? '#3c515a' : '#627983'; ctx.lineWidth = 0.38; ctx.stroke();

      const metal = ctx.createLinearGradient(-12, -130, 12, -130);
      for (const [at, colour] of rear ? [
        [0, '#394e60'], [0.1, '#a9becb'], [0.2, '#617b86'], [0.68, '#708893'], [0.92, '#b8cbd1'], [1, '#475d6a'],
      ] : [
        [0, '#425766'], [0.065, '#d8e4e6'], [0.13, '#9cafb7'], [0.24, '#738d98'],
        [0.5, '#7f959c'], [0.77, '#859da5'], [0.9, '#b8c9d0'], [0.97, '#e6eeeb'], [1, '#637c89'],
      ]) metal.addColorStop(at, colour);
      handlePath(ctx, shift); ctx.fillStyle = metal; ctx.fill();
      ctx.strokeStyle = rear ? 'rgba(47,66,77,.78)' : 'rgba(66,87,97,.62)';
      ctx.lineWidth = 0.48; ctx.stroke();

      ctx.save(); handlePath(ctx, shift); ctx.clip();
      ctx.shadowColor = 'transparent'; ctx.shadowBlur = 0;
      // Fine brushed-metal strokes beneath the ink, never over the flowers.
      for (let y = -207; y < -52; y += 3) {
        ctx.beginPath(); ctx.moveTo(-12 + shift(y), y); ctx.lineTo(12 + shift(y), y - 0.2);
        ctx.strokeStyle = y % 2 ? 'rgba(224,236,236,.08)' : 'rgba(42,61,71,.08)';
        ctx.lineWidth = 0.28; ctx.stroke();
      }
      if (!rear) floralPrint(ctx, shift);
      ctx.restore();
      ctx.shadowColor = 'transparent'; ctx.shadowBlur = 0;

      // Long silver bevels and the sharp hooked jaw carry the strongest reflection.
      ctx.beginPath(); ctx.moveTo(-9.4 + shift(-204), -204);
      ctx.bezierCurveTo(-10.4 + shift(-159), -159, -8.4 + shift(-87), -87, -6.85 + shift(-51), -51);
      ctx.strokeStyle = rear ? 'rgba(206,224,232,.5)' : 'rgba(243,252,250,.9)';
      ctx.lineWidth = rear ? 0.43 : 0.65; ctx.stroke();
      ctx.beginPath(); ctx.moveTo(9.6 + shift(-205), -205);
      ctx.bezierCurveTo(10.1 + shift(-159), -159, 9.1 + shift(-86), -86, 7.1 + shift(-52), -52);
      ctx.strokeStyle = 'rgba(31,51,64,.5)'; ctx.lineWidth = 0.48; ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-5.9 + shift(-49), -49);
      ctx.bezierCurveTo(-7.6 + shift(-36), -36, -8.3 + shift(-29), -29, -6.8 + shift(-24), -24);
      ctx.bezierCurveTo(-4.9 + shift(-19), -19, -0.8 + shift(-6), -6, shift(-0.9), -0.9);
      ctx.strokeStyle = rear ? 'rgba(198,229,237,.7)' : '#f4ffff';
      ctx.lineWidth = rear ? 0.36 : 0.48; ctx.stroke();
      ctx.beginPath(); ctx.moveTo(4.9 + shift(-49), -49);
      ctx.bezierCurveTo(2.5 + shift(-38), -38, -2.8 + shift(-28), -28, -3.2 + shift(-25), -25);
      ctx.strokeStyle = '#253f4b'; ctx.lineWidth = 0.4; ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-7.2 + shift(-50.8), -50.8); ctx.lineTo(6.7 + shift(-50.8), -50.8);
      ctx.strokeStyle = 'rgba(233,242,239,.9)'; ctx.lineWidth = 0.8; ctx.stroke();
    }

    // Folded tail: a restrained U rim joining the plates, with a dark inner crease.
    const fold = ctx.createLinearGradient(-11, -221, 11, -208);
    fold.addColorStop(0, '#5d7684'); fold.addColorStop(0.28, '#dfece9');
    fold.addColorStop(0.52, '#f4faf0'); fold.addColorStop(0.8, '#8eaab4'); fold.addColorStop(1, '#4d6979');
    ctx.beginPath(); ctx.moveTo(-10.45, -207.2);
    ctx.bezierCurveTo(-11.4, -223.8, 11.4, -223.8, 10.45, -207.2);
    ctx.lineTo(8.6, -207.5);
    ctx.bezierCurveTo(9.25, -219.5, -9.25, -219.5, -8.6, -207.5);
    ctx.closePath(); ctx.fillStyle = fold; ctx.fill();
