import { STAGES, createGameState, placeSticker, undoLast, getProgress, isValidDrop, serializeState, resetState } from './logic.js';
import { LEVEL, ITEMS, BY_ID, VIEWS } from './level.js';

const $ = id => document.getElementById(id);
const canvas = $('scene'), ctx = canvas.getContext('2d', { alpha: false });
const overlay = $('drag-layer'), dragCtx = overlay.getContext('2d');
const STORAGE_KEY = 'scenery-stickers:bookshop:v1';
const SETTINGS_KEY = 'scenery-stickers:settings:v1';
const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
let state, settings = { sound:false, hints:true };
let persistent = true;
try {
  state = createGameState(localStorage.getItem(STORAGE_KEY));
  const saved = JSON.parse(localStorage.getItem(SETTINGS_KEY) || '{}');
  settings = { sound: saved.sound === true, hints: saved.hints !== false };
} catch { state = createGameState(); persistent = false; }
let baseImage, atlasImage, ready = false, sprites = new Map(), silhouettes = new Map();
let width = 1, height = 1, dpr = 1, rect;
let view = { scale:1, tx:0, ty:0 }, cameraTween = null, fullView = false;
let selected = null, gesture = null, flight = null, burst = [], frameId = null;
let toastTimer = 0, stageTimer = 0, audioContext, lastTap = 0;
let transitionLocked = false, alive = true, exportURL = null;

function persist() {
  try { localStorage.setItem(STORAGE_KEY, serializeState(state)); }
  catch { persistent = false; }
  $('save-note').textContent = persistent ? '进度会自动保存' : '本次进度暂存于当前页面';
}
function persistSettings() {
  try { localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings)); } catch {}
}
function toast(message) {
  clearTimeout(toastTimer);
  $('toast').textContent = message;
  $('toast').classList.add('visible');
  toastTimer = setTimeout(() => $('toast').classList.remove('visible'), 1800);
}
function loadImage(url) {
  return new Promise((resolve,reject) => {
    const img = new Image(); img.onload = () => resolve(img); img.onerror = () => reject(new Error('image load failed')); img.src = url;
  });
}
function makeSprites() {
  for (const item of ITEMS) {
    const [x,y,w,h] = item.crop;
    const sprite = document.createElement('canvas'); sprite.width = w; sprite.height = h;
    sprite.getContext('2d').drawImage(atlasImage,x,y,w,h,0,0,w,h);
    const grey = document.createElement('canvas'); grey.width = w; grey.height = h;
    const c = grey.getContext('2d'); c.drawImage(sprite,0,0);
    c.globalCompositeOperation = 'source-in'; c.fillStyle = '#526153'; c.fillRect(0,0,w,h);
    sprites.set(item.id,sprite); silhouettes.set(item.id,grey);
  }
}
function fullCamera() {
  const scale = Math.min(width / LEVEL.width, height / LEVEL.height);
  return { scale, tx:(width-LEVEL.width*scale)/2, ty:(height-LEVEL.height*scale)/2 };
}
function clampCamera(camera) {
  const imageW = LEVEL.width*camera.scale, imageH = LEVEL.height*camera.scale;
  return {
    scale:camera.scale,
    tx:imageW <= width ? (width-imageW)/2 : Math.min(0,Math.max(width-imageW,camera.tx)),
    ty:imageH <= height ? (height-imageH)/2 : Math.min(0,Math.max(height-imageH,camera.ty)),
  };
}
function stageCamera(zoomOverride) {
  const focus = VIEWS[state.stage], scale = fullCamera().scale*(zoomOverride ?? focus.zoom);
  return clampCamera({ scale,tx:width/2-focus.x*scale,ty:height/2-focus.y*scale });
}
function moveCamera(target, animate = true) {
  if (gesture || flight) return;
  target = clampCamera(target);
  if (!animate || reducedMotion) { view = target; cameraTween = null; }
  else cameraTween = { from:{...view},to:target,start:performance.now(),duration:380 };
  schedule();
}
function resize() {
  const bounds = $('scene-shell').getBoundingClientRect();
  width = Math.max(1,bounds.width); height = Math.max(1,bounds.height);
  dpr = Math.min(devicePixelRatio || 1,2,Math.sqrt(2200000/(width*height)));
  canvas.width = Math.round(width*dpr); canvas.height = Math.round(height*dpr);
  overlay.width = Math.round(innerWidth*dpr); overlay.height = Math.round(innerHeight*dpr);
  rect = canvas.getBoundingClientRect();
  cancelGesture(false); cameraTween = null;
  view = state.completed || fullView ? fullCamera() : stageCamera();
  schedule();
}
function screenToWorld(x,y) {
  rect = canvas.getBoundingClientRect();
  return { x:(x-rect.left-view.tx)/view.scale, y:(y-rect.top-view.ty)/view.scale };
}
function worldToScreen(x,y) {
  rect = canvas.getBoundingClientRect();
  return { x:rect.left+view.tx+x*view.scale, y:rect.top+view.ty+y*view.scale };
}
function targetCenter(item) { return {x:item.target.x+item.target.w/2,y:item.target.y+item.target.h/2}; }
function withinScene(x,y) {
  rect = canvas.getBoundingClientRect();
  return x>=rect.left && x<=rect.right && y>=rect.top && y<=rect.bottom;
}
function dropTolerance(item) { return Math.max(24,Math.min(43,Math.min(item.target.w,item.target.h)*view.scale*.48))/view.scale; }
function nearTarget(id,x,y) { return withinScene(x,y) && isValidDrop(BY_ID[id],screenToWorld(x,y),dropTolerance(BY_ID[id])); }
function drawSticker(c,item,alpha = 1) {
  c.globalAlpha = alpha;
